import styled from "styled-components";

export const PropertiesContainer = styled.div`
    width: 100%;
    margin-top:20px;
    display:flex;


`

export const PropertyItemContainer = styled.div`
    width: 90%;
    height:50%;
    display:flex;
    align-items: center;
    justify-content: space-between;

    p{
        font-family: Roboto, sans serif;
    }

`
